# Since we can't import the library, let me implement a simple version
# of the key functionality to analyze the problem

inputs = ['dwh', 'yfj', 'ddz', 'ww', 'ybcj']
outputs = ['awh', 'yfage', 'aaz', 'ww', 'ybcyaage']

# Find changed pairs manually
changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Analyze each change
print("\nAnalysis:")
for idx, inp, outp in changed_pairs:
    print(f"'{inp}' -> '{outp}': ", end="")

    # Simple analysis of differences
    if len(inp) == len(outp):
        # Same length - look for substring changes
        diff_positions = []
        for i in range(len(inp)):
            if inp[i] != outp[i]:
                diff_positions.append(i)
        if len(diff_positions) == 1:
            print(f"position {diff_positions[0]}: '{inp[diff_positions[0]]}' -> '{outp[diff_positions[0]]}'")
        else:
            print("multiple differences")
    elif len(inp) > len(outp):
        # Removal
        print(f"removal of substring")
    else:
        # Addition
        print(f"addition of substring")

